      "number": 10,
      "stem": "嘉仁公司於 X6 年初以$60,000 購得一專利權，其法定年限為十五年。嘉仁公司估計該專利權之經濟效益年限尚有十二年。X9 年初嘉仁公司在此專利權之訴訟中獲判勝訴，使專利權之效益得以維持，相關訴訟支出共計$18,000。試問嘉仁公司 X9 年專利權之攤銷費用為何？",
