      "stem": "甲公司經過投標取得與乙客戶簽訂一項三年期服務合約，管理乙客戶之資料中心。該合約可於期滿後每次續約一年。甲公司預期乙客戶將會再續約二次。甲公司為準備該項投標的支出為$17,000，另在與乙客戶簽訂合約時，甲公司即支付員工$6,000 之銷售佣金。下列敘述何者正確？",
