      "stem": "甲公司於 X1 年 1 月 1 日以$1,330,000(不含交易成本$2,860)發行可買回公司債，甲公司得自 X3 年 1 月 1 日起，以$1,350,000(另加應計利息)買回該公司債。發行時經評價之結果，公司債中嵌入式之買回權資產的公允價值為$50,000。甲公司判定買回權與公司債兩者經濟特性及風險並未緊密關聯，因此決定單獨認列嵌入衍生工具，並對公司債採用攤銷後成本法。則甲公司於 X1 年 1 月 1 日認列應付公司債之帳面金額為何？",
