      "session": 1,
      "subject": "accounting",
      "sourceId": "accounting-11",
      "number": 17,
      "stem": "甲公司之董事會於 X1 年 10 月 16 日決議辦理現金增資，保留供員工認購股數為 2,000,000 股，每股面額$10，認購價格為每股$40，當日股票市價為每股$50。甲公司已於該日通知員工得認購之數量與價格。增資基準日訂為 X1 年 11 月 24 日。甲公司採選擇權定價模式估計所給與認購新股權利之給與日每單位公允價值為$10.05，員工繳款截止日為 X1 年 11 月 15 日。截至 X1 年 11 月 15 日員工共認購 1,800,000 股。公司現金增資最終仍完成。有關該筆股份基礎給付交易之結果，對甲公司權益之變動，下列敘述何者正確？",
