      "number": 23,
      "stem": "甲公司 X1 年底有 A、B 二個現金產生單位，可回收金額皆大於其帳面金額，但A、B 二個現金產生單位共用之公司電力設施，並無現金流入。相關單位 X1 年底減損測試之資訊如下：帳面金額可回收金額說明 A 現金產生單位 $12,000,000 $14,400,000 帳面金額未包含電力設施 B 現金產生單位 $6,000,000 $8,100,000 帳面金額未包含電力設施電力設施 $9,000,000 NA 依帳面金額比例分攤至現金產生單位甲公司於 X1 年底應認列電力設施之減損損失為多少金額？",
