      "session": 2,
      "subject": "accounting",
      "sourceId": "accounting-09",
      "number": 18,
      "stem": "依國際財務報導準則(簡稱 IFRS16)針對「租賃(Leases)」應適用的適當會計政策與揭露，試問：以下敘述何者有誤？甲、承租人在租賃期間開始日，承租人應以租賃開始日所決定之租賃資產公允價值或最低租賃給付現值兩者孰高者，於其財務狀況表內將融資租賃認列為資產與負債。乙、承租人於營業租賃下之租賃給付應按直線基礎於租賃期間內認列為費用，除非另一種有系統之基礎更能代表使用者效益之時間型態。丙、一項租賃如未移轉附屬於租賃標的物所有權之幾乎所有風險與報酬，則應分類為融資租賃。丁、售後租回交易若形成融資租賃，出售人兼承租人對銷售價款超過帳面金額之部分不得立即認列為收益，而應予遞延並於租賃期間攤銷。",
      "options": [
        "甲、丙",
        "乙、丙",
        "甲、丁",
        "乙、丁"
      ],
      "answer": [
        "A"
      ],
      "sourceIds": [
        "accounting-09"
      ],
      "sourceRefs": [
        {
          "chapterId": "accounting-09",
          "sectionIndex": 1
        }
      ]
