      "number": 22,
      "stem": "依國際會計準則第 24 號「關係人揭露」(簡稱 IAS24)，其中第 18 段規定若報導個體於財務報表涵蓋期間內有關係人交易，應揭露關係人關係之性質，及關係人交易與未結清餘額(包括承諾)之相關資訊。試問：其揭露應完整包含下列哪些項目？甲、交易金額；乙、未結清餘額（不包括承諾）；丙、未結清餘額（包括承諾），及其條款及條件，包括是否有擔保及供清償之對價之性質；以及收受或提供任何保證之詳細資訊；丁、與未結清餘額有關之呆帳準備；戊、當期對應收關係人款之壞帳或呆帳所認列之費用。",
      "options": [
        "甲、乙、丁",
        "甲、丙、戊",
        "甲、丙、丁、戊",
        "甲、乙、丁、戊"
      ],
      "answer": [
        "C"
      ],
      "sourceIds": [
        "accounting-01"
      ],
