      "stem": "依國際會計準則第 29 號「高度通貨膨脹經濟下之財務報導」原則：於通貨膨脹期間，在資產與負債未與物價水準連動之範圍內，若企業持有之貨幣性負債超過貨幣性資產，將有購買力利益。則該淨貨幣部位之損益，應如何處理？",
