      "stem": "甲公司 X1 年 1 月底及 2 月底未兌現支票金額分別為$34,000 及$45,000。若甲公司於 X1 年 2 月份實際開立支票之金額為$337,500，則甲公司 X1 年 2 月份銀行對帳單之支票支出金額為多少元？",
