      "year": 114,
      "session": 2,
      "subject": "accounting",
      "sourceId": "accounting-19",
      "number": 32,
      "stem": "甲公司於 X1 年初購買價值$4,000,000 的油井設備。該設備耐用年限為 10 年，以直線法提列折舊，無殘值。10 年後拆除該設備的預計成本為$800,000(以利率 10%設算的現值為 $308,440)，根據該公司現況 10%利率應屬合理。試問：甲公司 X2 年度與該交易相關事項應認列費用之金額為何？",
