      "stem": "甲公司 X1 年初開始動工建造自用廠房，預計 X2 年底完工。X1 年為建造該廠房之累積現金支出共$1,600,000，X1 年 12 月 31 日尚有未支付之應付工程款$200,000，X1 年建造該廠房資本化之利息費用金額為$320,000。X2 年 1 月 1 日支付 X1 年 12 月 31 日之應付工程款 $200,000，X2 年 7 月 1 日支付工程成本$1,100,000，試問 X2 年累積支出平均數淨額為多少元？",
