      "sessionId": "114Q3",
      "year": 114,
      "session": 3,
      "subject": "accounting",
      "sourceId": "accounting-10",
      "number": 18,
      "stem": "大安公司於 X2 年 3 月 15 日以每股$50 購買 WW 公司普通股 15,000 股，並將其分類為「透過其他綜合損益按公允價值衡量」之股票投資。X2 年 10 月 25 日，WW 公司宣告並發放每股 $5 之現金股利（該股利非屬成本回收）及 10%之股票股利。若截至 X2 年 12 月 31 日，WW 公司普通股每股之公允價值為$57.5，請問：該項股票投資對大安公司 X2 年度本期其他綜合損益之影響金額為多少？（不考慮所得稅）",
