      "sessionId": "114Q3",
      "year": 114,
      "session": 3,
      "subject": "accounting",
      "sourceId": "accounting-20",
      "number": 22,
      "stem": "新社公司營業收入淨額為$2,000,000，變動營業成本及費用為$1,200,000，營業利益為 $400,000。請問：新社公司之營運槓桿度(DOL)為多少？",
