      "number": 28,
      "stem": "甲公司原持有乙公司 30%的股權（對乙公司具有重大影響力），並採權益法處理。該投資帳面金額為$300。X2 年初，甲公司又收購乙公司額外 30%股權，使持股比例提升至 60%，並對乙公司取得控制。交易日當日，甲公司原本持有乙公司 30%股權之公允價值為$500。對於此次股權變動，甲公司應作的會計處理，下列何者正確？",
